def migrar_catalogos_geograficos(apps, schema_editor):
    Departamento = apps.get_model("geografia", "Departamento")
    Municipio = apps.get_model("geografia", "Municipio")
    MunicipioAnterior = apps.get_model("ubicaciones", "Municipio")
    Ubicacion = apps.get_model("ubicaciones", "Ubicacion")
    alias = schema_editor.connection.alias
    nombres = dict(DEPARTAMENTOS)

    codigos = set(
        MunicipioAnterior.objects.using(alias).values_list("departamento", flat=True)
    )
    codigos.update(
        Ubicacion.objects.using(alias).values_list("departamento", flat=True)
    )
    codigos.update(nombres)

    for codigo in codigos:
        Departamento.objects.using(alias).get_or_create(
            codigo=codigo,
            defaults={"nombre": nombres.get(codigo, codigo.replace("_", " ").title())},
        )

    departamentos = {
        departamento.codigo: departamento
        for departamento in Departamento.objects.using(alias).all()
    }
    for municipio in MunicipioAnterior.objects.using(alias).all():
        Municipio.objects.using(alias).get_or_create(
            departamento_id=departamentos[municipio.departamento].pk,
            nombre=municipio.nombre,
        )


def restaurar_municipios_anteriores(apps, schema_editor):
    MunicipioAnterior = apps.get_model("ubicaciones", "Municipio")
    Municipio = apps.get_model("geografia", "Municipio")
    alias = schema_editor.connection.alias
    MunicipioAnterior.objects.using(alias).all().delete()
    MunicipioAnterior.objects.using(alias).bulk_create(
        [
            MunicipioAnterior(
                departamento=municipio.departamento.codigo,
                nombre=municipio.nombre,
            )
            for municipio in Municipio.objects.using(alias).select_related("departamento")
        ]
    )


